using System.Collections.Generic;
using System.Linq;
using System.Text;
using RimWorld;
using UnityEngine;
using Verse;

namespace RimPunkCE
{
    public enum QuickhackCategory { Combat, Control, Covert, Ultimate }

    /// <summary>
    /// Per-quickhack data (prompts/quickhacks/manifest.md, generated by Source/Tools/gen_quickhacks.py). Every tiered
    /// number has 6 entries (T1..Iconic); tiers below <see cref="minTier"/> repeat the minimum. The ability reads them
    /// at the caster's learned tier, so one AbilityDef covers every tier.
    /// </summary>
    public class QuickhackExtension : DefModExtension
    {
        public QuickhackCategory category;
        public CyberTier minTier = CyberTier.T1;
        public CyberTier maxTier = CyberTier.T5;

        public TieredFloat ram;
        public TieredFloat upload;
        public TieredFloat duration;
        /// <summary>Main strength: damage, damage per second, debuff size... (meaning depends on the effect comp).</summary>
        public TieredFloat magnitude;
        /// <summary>Spread: number of extra targets.</summary>
        public TieredFloat spread;
        public float spreadRadius = 8f;

        public bool untraceable;
        /// <summary>Untraceable from this tier on (System Collapse t5).</summary>
        public CyberTier untraceableFromTier = CyberTier.Iconic;
        public bool affectsMechanoids = true;
        public bool humanlikeOnly;
        /// <summary>Skip targets that already carry this hediff (most quickhacks can't be uploaded twice).</summary>
        public HediffDef blockedIfTargetHas;

        /// <summary>AI: never (covert utility), or only on targets matching the effect comp's own rule.</summary>
        public bool aiNever;

        public float Eval(TieredFloat v, CyberTier tier, float fallback = 0f) =>
            v == null ? fallback : v.Evaluate(TierUtility.Clamp(tier, minTier, CyberTier.Iconic), CyberTier.T1, CyberTier.Iconic);

        public bool IsUntraceable(CyberTier tier) => untraceable || tier >= untraceableFromTier;
    }

    /// <summary>
    /// A learned quickhack. The tier is what the pawn learned (CompCyberTracker.QuickhackTier), not an implant's tier.
    /// Needs a cyberdeck installed. RAM is checked here and spent by CompAbilityEffect_QuickhackCore.
    /// </summary>
    public class QuickhackAbility : CyberwareAbility
    {
        public QuickhackAbility() { }
        public QuickhackAbility(Pawn pawn) : base(pawn) { }
        public QuickhackAbility(Pawn pawn, AbilityDef def) : base(pawn, def) { }
        public QuickhackAbility(Pawn pawn, Precept sourcePrecept) : base(pawn, sourcePrecept) { }
        public QuickhackAbility(Pawn pawn, Precept sourcePrecept, AbilityDef def) : base(pawn, sourcePrecept, def) { }

        private QuickhackExtension extCached;
        public QuickhackExtension Ext => extCached ??= def.GetModExtension<QuickhackExtension>();

        public CyberTier Tier => pawn.GetCyberTracker()?.QuickhackTier(def) ?? Ext?.minTier ?? CyberTier.T1;
        public override CyberTier SourceTier => Tier;

        public float Eval(TieredFloat v, float fallback = 0f) => Ext?.Eval(v, Tier, fallback) ?? fallback;

        /// <summary>RAM for this upload, after temporary reductions (Synapse Burnout / Suicide / Detonate t5 stacks).</summary>
        public float RamCost => Mathf.Max(0f, Eval(Ext?.ram, 1f) - (pawn.GetCyberTracker()?.QuickhackRamDiscount(def) ?? 0f));

        public float UploadSeconds => Eval(Ext?.upload, verb?.verbProps?.warmupTime ?? 1f);

        public bool Overclocked => QuickhackUtility.Overclocked(pawn);

        public override string BlockReason()
        {
            string b = base.BlockReason();
            if (b != null) return b;
            var tracker = pawn.GetCyberTracker();
            if (tracker == null || !tracker.HasCyberdeck) return "RPC_NeedsCyberdeck".Translate();
            if (Hediff_Quickhack.TargetHas(pawn, x => x.blocksQuickhacks)) return "RPC_BlockedBySonicShock".Translate();
            if (!Overclocked && tracker.Ram < RamCost) return "RPC_NotEnoughRam".Translate(RamCost.ToString("0.#"));
            return null;
        }

        public override string Tooltip
        {
            get
            {
                var ext = Ext;
                if (ext == null) return base.Tooltip;
                var sb = new StringBuilder(base.Tooltip);
                sb.AppendLine().AppendLine();
                sb.AppendLine("RPC_QuickhackTooltip".Translate(("RPC_QuickhackCategory_" + ext.category).Translate(), Tier.Label(),
                    RamCost.ToString("0.#"), UploadSeconds.ToString("0.#")));
                float dur = Eval(ext.duration);
                if (dur > 0f) sb.AppendLine("RPC_QuickhackDuration".Translate(dur.ToString("0.#")));
                if (ext.IsUntraceable(Tier)) sb.AppendLine("RPC_QuickhackUntraceable".Translate());
                return sb.ToString().TrimEndNewlines();
            }
        }

        public override bool Activate(LocalTargetInfo target, LocalTargetInfo dest)
        {
            bool ok = base.Activate(target, dest);
            if (ok && Ext != null && !Ext.IsUntraceable(Tier) && Tier >= CyberTier.T4 && pawn.GetCyberTracker() is CompCyberTracker t)
                t.lastHighTierQuickhackTick = Find.TickManager.TicksGame; // NetWatch trace
            return ok;
        }
    }

    /// <summary>
    /// First comp of every quickhack: spends RAM (Overclock: missing RAM costs health), runs Self-ICE, rolls the crit and
    /// stores the upload context the effect comps read. Effect comps do nothing when the upload was negated.
    /// </summary>
    public class CompProperties_QuickhackCore : CompProperties_AbilityEffect
    {
        public CompProperties_QuickhackCore() => compClass = typeof(CompAbilityEffect_QuickhackCore);
    }

    public class CompAbilityEffect_QuickhackCore : CompAbilityEffect
    {
        public bool negated;
        public float critFactor = 1f;
        public float ramSpent;

        public override void Apply(LocalTargetInfo target, LocalTargetInfo dest)
        {
            base.Apply(target, dest);
            var ability = (QuickhackAbility)parent;
            var caster = parent.pawn;
            negated = false;
            critFactor = 1f;
            ramSpent = ability.RamCost;
            QuickhackUtility.SpendRam(caster, ramSpent);

            if (target.Thing is Pawn victim && victim.HostileTo(caster) && HediffComp_SelfIce.TryNegate(victim))
            {
                negated = true;
                Diag.Count("quickhack-negated");
                MapComponent_Netrun.Notify_Result(victim, NetrunResult.Resisted);
                BarkUtility.Say(victim, BarkKeys.NetrunResisted);
                return;
            }
            float crit = caster.GetStatValue(RPStatDefOf.RPC_QuickhackCritChance);
            if (crit > 0f && Rand.Chance(crit))
            {
                critFactor = 2f;
                if (caster.Map != null && target.HasThing) MoteMaker.ThrowText(target.Thing.DrawPos, caster.Map, "RPC_Crit".Translate(), Color.cyan, 2f);
            }
            Diag.Count("quickhack");
            if (target.HasThing) MapComponent_Netrun.Notify_Result(target.Thing, NetrunResult.Uploaded);
            if (caster.Faction?.IsPlayer == true)
                Diag.Event("quickhack", $"{Diag.Describe(caster)} uploaded {parent.def.defName} {ability.Tier} ({ramSpent:0.#} RAM{(critFactor > 1f ? ", crit" : "")}) to {(target.Thing is Pawn tp ? Diag.Describe(tp) : target.ToString())}");
        }

        public override bool CanApplyOn(LocalTargetInfo target, LocalTargetInfo dest) => QuickhackUtility.ValidTarget((QuickhackAbility)parent, target.Thing, false);

        public override bool Valid(LocalTargetInfo target, bool throwMessages = false) =>
            base.Valid(target, throwMessages) && QuickhackUtility.ValidTarget((QuickhackAbility)parent, target.Thing, throwMessages);
    }

    /// <summary>Base for quickhack effect comps: tier, extension, scaling, and "skip if negated".</summary>
    public abstract class CompAbilityEffect_QuickhackEffect : CompAbilityEffect
    {
        protected QuickhackAbility Hack => (QuickhackAbility)parent;
        protected QuickhackExtension Ext => Hack.Ext;
        protected CyberTier Tier => Hack.Tier;
        protected Pawn Caster => parent.pawn;
        protected CompAbilityEffect_QuickhackCore Core => parent.CompOfType<CompAbilityEffect_QuickhackCore>();
        protected bool Negated => Core?.negated == true;
        protected float Eval(TieredFloat v, float fallback = 0f) => Ext.Eval(v, Tier, fallback);

        /// <summary>Damage multiplier: quickhack + cyberware damage stats, crit.</summary>
        protected float DamageFactor =>
            Caster.GetStatValue(RPStatDefOf.RPC_CyberwareDamageFactor) * Caster.GetStatValue(RPStatDefOf.RPC_QuickhackDamageFactor) * (Core?.critFactor ?? 1f);

        /// <summary>Duration with deck bonuses for combat quickhacks (Biotech t2+, NetDriver).</summary>
        protected int DurationTicks(float seconds)
        {
            if (Ext.category == QuickhackCategory.Combat) seconds *= 1f + QuickhackUtility.DeckValue(Caster, "combatQuickhackDuration");
            return CyberUtility.SecondsToTicks(seconds);
        }

        protected float SpreadRadius => Ext.spreadRadius * (1f + QuickhackUtility.DeckValue(Caster, "quickhackSpreadDistance"));

        public sealed override void Apply(LocalTargetInfo target, LocalTargetInfo dest)
        {
            base.Apply(target, dest);
            if (Negated || !target.HasThing) return;
            ApplyHack(target.Thing);
        }

        protected abstract void ApplyHack(Thing target);

        /// <summary>AI rule; base: any standing hostile the quickhack can affect.</summary>
        public override bool AICanTargetNow(LocalTargetInfo target)
        {
            if (Ext == null || Ext.aiNever) return false;
            return target.Thing is Pawn p && !p.Downed && p.HostileTo(Caster) && QuickhackUtility.ValidTarget(Hack, p, false) && AIWants(p);
        }

        protected virtual bool AIWants(Pawn target) => true;
    }

    public static class QuickhackUtility
    {
        public static bool Overclocked(Pawn pawn) =>
            QuickhackDefOf.RPC_Overclock != null && pawn?.health?.hediffSet?.HasHediff(QuickhackDefOf.RPC_Overclock) == true;

        /// <summary>Spend RAM; with Overclock, missing RAM is paid in health (1 electrical damage per unit, spread over the body).</summary>
        public static void SpendRam(Pawn pawn, float amount)
        {
            var tracker = pawn.GetCyberTracker();
            if (tracker == null || amount <= 0f) return;
            float missing = tracker.SpendRamAllowingDebt(amount);
            if (missing <= 0f) return;
            int hits = Mathf.CeilToInt(missing);
            for (int i = 0; i < hits; i++)
            {
                var part = pawn.health.hediffSet.GetNotMissingParts(BodyPartHeight.Undefined, BodyPartDepth.Outside).RandomElementWithFallback();
                pawn.TakeDamage(new DamageInfo(RPDefOf.RPC_Electrical, 1f, 999f, -1f, null, part));
                if (pawn.Dead) break;
            }
            Diag.Event("quickhack", $"{Diag.Describe(pawn)} overclocked: {missing:0.#} RAM paid in health");
        }

        /// <summary>Highest value of a key across installed cyberdecks (Biotech / NetDriver duration, Raven spread...).</summary>
        public static float DeckValue(Pawn pawn, string key)
        {
            float best = 0f;
            foreach (var c in pawn.InstalledCyberware())
                if (c.Ext?.osType == CyberOsType.Cyberdeck) best = Mathf.Max(best, c.GetValue(key, 0f));
            return best;
        }

        public static bool ValidTarget(QuickhackAbility hack, Thing t, bool throwMessages)
        {
            if (!(t is Pawn p) || p.Dead || p == hack.pawn) return false;
            string fail = InvalidReason(hack, p);
            if (fail == null) return true;
            if (throwMessages)
            {
                Messages.Message(fail.Translate(), p, MessageTypeDefOf.RejectInput, false);
                MapComponent_Netrun.Notify_Result(p, NetrunResult.Immune);
            }
            return false;
        }

        /// <summary>Translation key for why this hack can't affect this pawn, or null if it can.</summary>
        public static string InvalidReason(QuickhackAbility hack, Pawn p)
        {
            var ext = hack.Ext;
            if (ext == null) return null;
            if (p.RaceProps.IsMechanoid && !ext.affectsMechanoids) return "RPC_QuickhackNoMechanoids";
            if (ext.humanlikeOnly && !p.RaceProps.Humanlike) return "RPC_QuickhackHumanlikeOnly";
            if (ext.blockedIfTargetHas != null && p.health.hediffSet.HasHediff(ext.blockedIfTargetHas)
                && !(p.health.hediffSet.GetFirstHediffOfDef(ext.blockedIfTargetHas) is Hediff_Quickhack q && q.CanStack))
                return "RPC_QuickhackAlreadyAffected";
            return null;
        }

        /// <summary>Nearest standing pawns of the same side as <paramref name="from"/> (excluding it), for spreads.</summary>
        public static IEnumerable<Pawn> SpreadTargets(Pawn caster, Pawn from, float radius, int count, System.Func<Pawn, bool> valid)
        {
            if (from?.Map == null || count <= 0) return Enumerable.Empty<Pawn>();
            return from.Map.mapPawns.AllPawnsSpawned
                .Where(p => p != from && p != caster && !p.Dead && !p.Downed && p.HostileTo(caster) && p.Position.InHorDistOf(from.Position, radius) && valid(p))
                .OrderBy(p => p.Position.DistanceToSquared(from.Position))
                .Take(count).ToList();
        }

        public static bool HasAnyChrome(Pawn p) =>
            p.InstalledCyberware().Any() || p.health.hediffSet.hediffs.Any(ForeignCyberwareUtility.IsForeignImplant);
    }

    [DefOf]
    public static class QuickhackDefOf
    {
        public static HediffDef RPC_Overclock;
        public static HediffDef RPC_QH_CyberwareMalfunction;
        public static HediffDef RPC_QH_CrippleMovement;
        public static HediffDef RPC_QH_RebootOptics;
        public static HediffDef RPC_QH_WeaponGlitch;
        public static HediffDef RPC_QH_SonicShock;
        public static HediffDef RPC_QH_Baited;
        public static HediffDef RPC_QH_Pinged;
        public static HediffDef RPC_QH_SystemCollapse;
        public static HediffDef RPC_QH_MemoryWiped;
        public static MentalStateDef RPC_MemoryWiped;
        public static MentalStateDef RPC_HackedCyberpsychosis;
        public static AbilityDef RPC_Quickhack_ShortCircuit;
        public static AbilityDef RPC_Quickhack_Ping;
        public static AbilityDef RPC_Quickhack_BlackwallGateway;

        static QuickhackDefOf() => DefOfHelper.EnsureInitializedInCtor(typeof(QuickhackDefOf));
    }
}
